175: /**
176:  * The first month the balance is at or below zero: month 0 when the
177:  * buffer is already gone, null when the gap is not positive (no
178:  * shortfall can ever land), otherwise the integer ceiling of
179:  * bufferLeft divided by gap, written as one integer division so no
180:  * float touches the branch.
181:  */
182: function landfallMonthIndex(bufferLeft: number, gap: number): number | null {
183:   if (bufferLeft <= 0) {
184:     return 0
185:   }
186:   if (gap <= 0) {
187:     return null
188:   }
189:   return Math.floor((bufferLeft + gap - 1) / gap)
190: }
191: 
192: /**
193:  * The adaptive horizon: 12 months by default, extended to the
194:  * landfall month when that lands later than 12, and capped at 120.
195:  * A null landfall (no shortfall) always keeps the 12 month view.
196:  */
197: function horizonFor(landfallMonth: number | null): number {
198:   if (landfallMonth === null || landfallMonth <= DEFAULT_HORIZON_MONTHS) {
199:     return DEFAULT_HORIZON_MONTHS
200:   }
201:   return Math.min(landfallMonth, MAX_HORIZON_MONTHS)
202: }
